			// double check again, do not correct keeper state while migration is in progress
			if (!isCurrentMetaKeeperMasterMatch(clusterId, shardId)) {
				logger.info("[doCorrect][migrating, skip correct]cluster: {}, shard: {}", clusterId, shardId);
				return;
			}
			KeeperStateChangeJob job = createKeeperStateChangeJob(clusterId, survivedKeepers,
					currentMetaManager.getKeeperMaster(clusterId, shardId));
			job.future().addListener(new CommandFutureListener<Void>() {
				@Override
				public void operationComplete(CommandFuture<Void> commandFuture) throws Exception {
					logger.info("[{}][KeeperInfoCorrect]cluster: {}, shard: {}, result: {}",
							getClass(), clusterId, shardId, commandFuture.isSuccess());
				}
			});
			clusterShardExecutor.execute(new Pair<>(clusterId, shardId), job);
		}
	}

	/**
	 * Whether the keeper master recorded in current meta is consistent with the role of the current dc.
	 * <p>
	 * For primary dc, keeper's master should be one of the shard redises; for backup dc, keeper's master
	 * should not be a shard redis (it replicates from the active keeper of the primary dc). When this does
	 * not hold, a datacenter migration is in progress and correction commands must be withheld.
	 */
	protected boolean isCurrentMetaKeeperMasterMatch(String clusterId, String shardId) {
		Pair<String, Integer> keeperMaster = currentMetaManager.getKeeperMaster(clusterId, shardId);
		if (keeperMaster == null) {
			return false;
		}
		boolean keeperMasterIsRedis = isKeeperMasterRedis(clusterId, shardId, keeperMaster);
		if (metaCache.isCurrentDcPrimary(clusterId)) {
			return keeperMasterIsRedis;
		} else {
			return !keeperMasterIsRedis;
		}
	}

	private boolean isKeeperMasterRedis(String clusterId, String shardId, Pair<String, Integer> keeperMaster) {
		List<RedisMeta> redises = metaCache.getShardRedises(clusterId, shardId);
		if (redises == null) {
			return false;
		}
		for (RedisMeta redis : redises) {
			if (ObjectUtils.equals(redis.getIp(), keeperMaster.getKey())
					&& ObjectUtils.equals(redis.getPort(), keeperMaster.getValue())) {
				return true;
			}
		}
		return false;
